import{_ as o,l as n,o as e,c as i,v as r,p as l,x as t,d as A,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"DNS 记录类型","description":"","frontmatter":{"title":"DNS 记录类型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dns-rr.md","filePath":"cs/dns-rr.md","lastUpdated":1789023840000}'),p={name:"cs/dns-rr.md"};function h(E,a,T,_,S,N){const s=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="dns-记录类型" tabindex="-1">DNS 记录类型 <a class="header-anchor" href="#dns-记录类型" aria-label="Permalink to &quot;DNS 记录类型&quot;">​</a></h1><div class="epigraph"><p>同一名字下可以挂地址、别名、邮件交换、名字服务器；类型决定答案是什么对象，而不只是「有没有这个名字」。</p><footer>—— 据 RFC 1035 的 RR 格式；Kurose and Ross 对常用记录的整理</footer></div><p><a href="/cs/dns-recursive">上一课</a>走完递归与迭代。本课不重画根到权威。缺口是应答里的资源记录（RR）：A/AAAA 是地址，NS 是下一层权威，CNAME 是别名，MX 是邮件，TXT 是文本约定。解析器按<strong>问的类型</strong>取子集。本课不把 HTTP 方法提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/dns">DNS</a> 说「得到地址或其他记录」。若只有 A，<a href="/cs/ipv6-contrast">IPv6</a> 的双栈无法表达；若 CNAME 与 NS 在区顶混用，委托会坏。每条 RR 有所有者、类型、类、TTL、数据。缺口是<strong>类型作为模式</strong>，让后课 CDN 用同一名字返回不同地址成为合法，而不是协议外魔法。</p><p><span class="marginnote">CNAME 的目标要再查。别名链有深度限制。SOA 描述区的权威参数，不是给浏览器打开网页用的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查询：名字 + 类型。权威返回匹配 RR，以及胶水（NS 的 A/AAAA）以便解析器继续。否定缓存（NSEC 等属 DNSSEC 一线）本课只承认「不存在也要记一会儿」。应用选类型：浏览器要 A/AAAA，邮件要 MX。</p>',8)),(e(),l(c,null,{default:t(()=>[d(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8D%E5%AD%97%E5%8A%A0%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20AUTH%5B%22%E6%9D%83%E5%A8%81%E6%88%96%E7%BC%93%E5%AD%98%22%5D%0A%20%20AUTH%20--%3E%20A%5B%22A%20%2F%20AAAA%20%E5%9C%B0%E5%9D%80%22%5D%0A%20%20AUTH%20--%3E%20NS%5B%22NS%20%E5%A7%94%E6%89%98%22%5D%0A%20%20AUTH%20--%3E%20CN%5B%22CNAME%20%E5%86%8D%E8%A7%A3%E6%9E%90%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RR 把层次名字从「一台主机」扩成「一组类型化属性」。<a href="/cs/cdn-intuition">任播与 CDN</a> 后课会改 A/AAAA 的值或 NS 指向，类型系统不变。校验：UDP DNS 有长度与截断；真实性不是 RR 自带的，后课 TLS 用证书绑名字。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部类型注册表写进主干，不引入 SVCB/HTTPS 的全部键。对资源做 GET 的应用协议下一课 HTTP。</p><p>后课默认：解析结果是带类型的记录集。网页与 API 的方法与状态码是另一层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RR 以类型区分地址、委托、别名等。</li><li>查询必须带类型；CNAME 触发后续查找。</li><li>应用层 HTTP 下一课。</li><li>出处：RFC 1034/1035；Kurose and Ross。</li></ul>',7))])}const m=o(p,[["render",h]]);export{D as __pageData,m as default};
